:root {
  color-scheme: light;
  --background: #fff;
  --foreground: #17191e;
  --card: #fff;
  --muted: #f7f8fa;
  --subtle: #fbfcfe;
  --muted-foreground: #717680;
  --border: #e9ebef;
  --primary: oklch(0.692 0.141 243.716);
  --primary-foreground: #fff;
  --accent: #eff7ff;
  --blue: #308ad4;
  --blue-strong: #2677c4;
  --code-string: #24885e;
  --code-keyword: #8260bd;
  --code-call: #287fbe;
  --success: #26a578;
  --header: rgba(255, 255, 255, 0.87);
  --shadow: 0 20px 65px -30px #436eae36, 0 4px 14px #172b4d05;
  --mono: 'Cascadia Code', Consolas, monospace;
  --sans:
    'Public Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC',
    'Microsoft YaHei', sans-serif;
}
[data-theme='dark'] {
  color-scheme: dark;
  --background: oklch(0.235 0 0);
  --foreground: oklch(0.965 0 0);
  --card: oklch(0.285 0 0);
  --muted: oklch(0.305 0 0);
  --subtle: oklch(0.26 0 0);
  --muted-foreground: #a8adb7;
  --border: #ffffff16;
  --primary: oklch(0.54 0.142 248.516);
  --accent: #26394c;
  --blue: #73b9ef;
  --blue-strong: #8bc6fa;
  --code-string: #8dcea9;
  --code-keyword: #bba3ea;
  --code-call: #84bfea;
  --success: #65c49d;
  --header: #202020eb;
  --shadow: 0 20px 65px -30px #0009, 0 4px 14px #0001;
}
* {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
  scroll-padding-top: 90px;
}
body {
  /* Include child margins in the body height reported to the homepage host. */
  display: flow-root;
  margin: 0;
  background: var(--background);
  color: var(--foreground);
  font: 14px/1.65 var(--sans);
  -webkit-font-smoothing: antialiased;
}
h1,
h2,
h3,
p {
  margin: 0;
}
a {
  color: inherit;
  text-decoration: none;
}
button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  background: none;
  border: 0;
}
button:disabled {
  cursor: wait;
}
button,
a {
  -webkit-tap-highlight-color: transparent;
}
button:focus-visible,
a:focus-visible,
summary:focus-visible,
[tabindex='0']:focus-visible {
  outline: 3px solid #4b9fe48c;
  outline-offset: 4px;
}
svg {
  display: block;
}
img {
  display: block;
  object-fit: contain;
}
::selection {
  background: #83bfff55;
}
.container {
  width: min(1120px, calc(100% - 80px));
  margin-inline: auto;
}
.icon {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
}
.icon.small {
  width: 14px;
  height: 14px;
}
.svg-defs {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
}
.skip {
  position: fixed;
  top: -80px;
  left: 15px;
  padding: 10px 20px;
  background: var(--card);
  z-index: 100;
}
.skip:focus {
  top: 10px;
}
[hidden] {
  display: none !important;
}
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid var(--border);
  background: var(--header);
  backdrop-filter: blur(16px);
}
.header-inner {
  height: 68px;
  max-width: 1320px;
  width: calc(100% - 72px);
  margin: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 21px;
  font-weight: 650;
  letter-spacing: -0.8px;
}
.brand img {
  border-radius: 8px;
}
.brand-label {
  font-size: 8px;
  font-weight: 500;
  letter-spacing: 1.1px;
  color: var(--muted-foreground);
  border: 1px solid var(--border);
  padding: 2px 6px;
  border-radius: 4px;
  margin-left: 1px;
}
.navigation {
  display: flex;
  gap: 7px;
  margin-left: 40px;
}
.navigation a {
  font-size: 12px;
  color: var(--muted-foreground);
  padding: 7px 14px;
  border-radius: 7px;
  transition:
    background 0.2s,
    color 0.2s;
}
.navigation a:hover {
  background: var(--muted);
  color: var(--foreground);
}
.navigation .nav-active {
  color: var(--blue-strong);
  background: var(--accent);
}
.header-actions {
  display: flex;
  gap: 17px;
  align-items: center;
}
.icon-button {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 8px;
  color: var(--muted-foreground);
  transition: background 0.2s;
}
.icon-button:hover {
  background: var(--muted);
  color: var(--foreground);
}
.header-divider {
  height: 18px;
  width: 1px;
  background: var(--border);
}
.login-link {
  font-size: 12px;
}
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 44px;
  padding: 0 22px;
  border: 1px solid transparent;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 550;
  transition:
    background 0.2s,
    box-shadow 0.2s,
    transform 0.2s;
  white-space: nowrap;
}
.button:hover {
  transform: translateY(-1px);
}
.button:active {
  transform: translateY(0);
}
.button-primary {
  background: var(--primary);
  color: var(--primary-foreground);
  box-shadow: 0 3px 6px #1b6eab12;
}
.button-primary:hover {
  background: color-mix(in srgb, var(--primary) 90%, #124673);
  box-shadow: 0 4px 12px #368cd528;
}
.button-small {
  min-height: 35px;
  padding: 0 13px;
  font-size: 11px;
  gap: 15px;
}
.button-small .icon {
  width: 15px;
  height: 15px;
}
.button-outline {
  border-color: var(--border);
  background: var(--card);
  color: var(--foreground);
  box-shadow: 0 2px 3px #192b4203;
}
.button-outline:hover {
  background: var(--muted);
}
.mobile-menu {
  display: none;
}
.hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding-top: 58px;
}
.hero-glow {
  position: absolute;
  z-index: -2;
  top: 0;
  left: 0;
  right: 0;
  height: 790px;
  background:
    radial-gradient(ellipse 45% 48% at 25% 40%, #d9edff50, transparent),
    radial-gradient(ellipse 45% 50% at 78% 47%, #ede4ff66, transparent);
}
[data-theme='dark'] .hero-glow {
  opacity: 0.18;
}
.hero-grid {
  position: absolute;
  z-index: -1;
  top: 0;
  left: 0;
  right: 0;
  height: 850px;
  background-image:
    linear-gradient(to right, var(--border) 1px, transparent 1px),
    linear-gradient(to bottom, var(--border) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(
    ellipse 60% 70% at 50% 25%,
    #0005,
    transparent 80%
  );
}
.hero-intro {
  text-align: center;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  border: 1px solid #a9cfea58;
  border-radius: 100px;
  background: var(--card);
  padding: 5px 11px;
  font-size: 10px;
  color: var(--muted-foreground);
  box-shadow: 0 3px 8px #539ee708;
}
.hero-badge > .icon:first-child {
  color: var(--blue);
  width: 14px;
  height: 14px;
}
.hero-badge > span:last-of-type {
  color: var(--blue-strong);
}
.badge-separator {
  width: 1px;
  height: 12px;
  background: var(--border);
  margin-inline: 1px;
}
.hero h1 {
  font-size: 57px;
  letter-spacing: -2.6px;
  line-height: 1.25;
  font-weight: 720;
  margin-top: 23px;
}
.hero h1 > span {
  color: #4a98de;
  background: linear-gradient(110deg, #378ed2 15%, #548de4 65%, #8980d1);
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
.hero-description {
  font-size: 13px;
  line-height: 1.9;
  color: var(--muted-foreground);
  margin-top: 21px;
}
.hero-actions {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 25px;
}
.hero-perks {
  display: flex;
  justify-content: center;
  gap: 23px;
  margin-top: 19px;
  color: var(--muted-foreground);
  font-size: 10px;
}
.hero-perks span {
  display: flex;
  gap: 5px;
  align-items: center;
}
.hero-perks .icon {
  width: 12px;
  height: 12px;
  color: #87a6b9;
}
.workspace-wrap {
  margin-top: 43px;
  scroll-margin-top: 90px;
}
.workspace {
  border: 1px solid var(--border);
  background: var(--card);
  border-radius: 13px;
  box-shadow: var(--shadow);
  overflow: hidden;
  text-align: left;
}
.workspace-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 47px;
  border-bottom: 1px solid var(--border);
  padding: 0 20px;
  background: var(--subtle);
}
.workspace-title {
  display: flex;
  gap: 9px;
  align-items: center;
  font-size: 11px;
  color: var(--muted-foreground);
}
.workspace-title > .icon {
  width: 14px;
  height: 14px;
}
.window-dots {
  display: flex;
  gap: 5px;
}
.window-dots i {
  height: 7px;
  width: 7px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--muted-foreground) 28%, var(--card));
}
.window-dots i:first-child {
  background: #eea5a1;
}
.window-dots i:nth-child(2) {
  background: #edd096;
}
.window-dots i:nth-child(3) {
  background: #a1cfb1;
}
.workspace-divider {
  height: 13px;
  background: var(--border);
  width: 1px;
  margin-inline: 8px;
}
.workspace-top-right {
  display: flex;
  align-items: center;
  gap: 16px;
  color: var(--muted-foreground);
}
.workspace-top-right .icon {
  height: 14px;
  width: 14px;
}
.demo-tag {
  font-size: 9px;
  color: var(--muted-foreground);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 6px;
}
.workspace-body {
  display: grid;
  grid-template-columns: 205px minmax(0, 1fr) 305px;
  min-height: 340px;
}
.model-sidebar {
  padding: 18px 12px;
  background: var(--subtle);
  border-right: 1px solid var(--border);
}
.panel-label {
  font-size: 9px;
  color: var(--muted-foreground);
  display: flex;
  justify-content: space-between;
  padding: 0 8px;
  margin-bottom: 12px;
}
.panel-label > span {
  background: var(--muted);
  border: 1px solid var(--border);
  border-radius: 3px;
  padding: 0 4px;
  font-size: 8px;
}
.model-option {
  display: flex;
  align-items: center;
  width: 100%;
  text-align: left;
  padding: 11px 9px;
  gap: 10px;
  border: 1px solid transparent;
  border-radius: 7px;
  margin-bottom: 5px;
  transition:
    background 0.2s,
    border-color 0.2s;
}
.model-option:hover {
  background: var(--muted);
}
.model-option.selected {
  background: var(--accent);
  border-color: color-mix(in srgb, var(--blue) 24%, transparent);
}
.model-logo {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  border: 1px solid var(--border);
  background: var(--card);
  border-radius: 7px;
  flex-shrink: 0;
}
.model-logo svg {
  width: 20px;
  height: 20px;
}
.model-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.model-text strong {
  font-size: 11px;
  font-weight: 600;
}
.model-text small {
  font-size: 8px;
  color: var(--muted-foreground);
}
.selection-indicator {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  margin-left: auto;
  background: transparent;
}
.selected .selection-indicator {
  background: var(--blue);
}
.claude-logo,
.claude-color {
  color: #bd7960;
}
.gemini-logo,
.gemini-color {
  color: #718ce1;
}
.deepseek-logo,
.deepseek-color {
  color: #537fe1;
}
.sidebar-link {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 17px 8px 0;
  color: var(--muted-foreground);
  font-size: 9px;
}
.sidebar-link:hover {
  color: var(--blue);
}
.sidebar-link .icon {
  width: 12px;
  height: 12px;
}
.request-panel {
  min-width: 0;
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border);
}
.request-toolbar {
  height: 49px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--border);
  padding: 0 19px;
  gap: 12px;
}
.code-tabs {
  height: 100%;
  display: flex;
  gap: 23px;
}
.code-tab {
  font: 10px var(--mono);
  height: 100%;
  color: var(--muted-foreground);
  padding: 0 1px;
  border-bottom: 2px solid transparent;
}
.code-tab[aria-selected='true'] {
  color: var(--blue-strong);
  border-color: var(--blue);
}
.copy-code .icon {
  width: 14px;
  height: 14px;
}
.code-panel {
  padding: 17px 21px;
  overflow-x: auto;
  flex: 1;
  scrollbar-width: thin;
  min-width: 0;
}
pre {
  font: 10px/1.85 var(--mono);
  margin: 0;
  tab-size: 2;
  color: var(--foreground);
}
.token-keyword {
  color: var(--code-keyword);
}
.token-string {
  color: var(--code-string);
}
.token-call {
  color: var(--code-call);
}
.request-footer {
  height: 39px;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 18px;
  font: 8px var(--mono);
  color: var(--muted-foreground);
  white-space: nowrap;
}
.method {
  font-size: 8px;
  color: var(--success);
  background: color-mix(in srgb, var(--success) 9%, transparent);
  padding: 2px 5px;
  border-radius: 3px;
}
.protocol-tag {
  margin-left: auto;
  font: 8px var(--sans);
  color: var(--muted-foreground);
}
.response-panel {
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: linear-gradient(165deg, transparent, var(--subtle));
}
.response-heading {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--muted-foreground);
}
.response-heading > span:first-child {
  display: flex;
  align-items: center;
  gap: 7px;
}
.status-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
  background: var(--success);
}
.response-type {
  font: 8px var(--mono);
  color: var(--muted-foreground);
}
.response-user {
  margin-top: 20px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  background: var(--muted);
  border-radius: 7px;
}
.response-user > span {
  font: 8px var(--mono);
  color: var(--muted-foreground);
}
.response-user p {
  font-size: 10px;
  margin-top: 4px;
}
.response-assistant {
  margin-top: 15px;
  flex: 1;
}
.assistant-name {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 550;
}
.assistant-symbol svg {
  width: 17px;
  height: 17px;
}
.ai-label {
  font: 7px var(--mono);
  padding: 1px 3px;
  background: var(--accent);
  color: var(--blue);
  border-radius: 3px;
}
.response-content {
  font-size: 10px;
  line-height: 1.9;
  padding: 10px 0 12px;
  min-height: 115px;
  color: var(--muted-foreground);
  white-space: pre-line;
}
.response-content strong {
  font-weight: 550;
  color: var(--foreground);
}
.response-content p {
  margin-top: 7px;
}
.response-content.streaming::after {
  content: '▋';
  color: var(--blue);
  animation: blink 0.8s step-end infinite;
}
.button-run {
  background: var(--accent);
  color: var(--blue-strong);
  border-color: color-mix(in srgb, var(--blue) 16%, transparent);
  min-height: 32px;
  font-size: 10px;
  border-radius: 6px;
  width: 100%;
  gap: 6px;
}
.button-run .icon {
  width: 12px;
  height: 12px;
}
.button-run:hover {
  background: color-mix(in srgb, var(--blue) 14%, var(--card));
}
.button-run:disabled {
  opacity: 0.65;
}
.response-caption {
  text-align: center;
  font-size: 8px;
  color: var(--muted-foreground);
  margin-top: 7px;
}
.workspace-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--border);
  height: 33px;
  padding: 0 18px;
  background: var(--subtle);
  color: var(--muted-foreground);
  font-size: 8px;
}
.workspace-bottom > span {
  display: flex;
  align-items: center;
  gap: 6px;
}
.workspace-bottom .icon {
  width: 11px;
  height: 11px;
}
.ecosystem {
  padding: 36px 0 52px;
  text-align: center;
}
.ecosystem > p {
  font-size: 10px;
  color: var(--muted-foreground);
  margin-bottom: 22px;
}
.provider-logos {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 55px;
  color: var(--muted-foreground);
}
.provider-logos > span {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.7px;
}
.provider-logos svg {
  width: 23px;
  height: 23px;
}
.provider-logos .anthropic-word {
  font-family: Georgia, serif;
  font-size: 23px;
  font-weight: 500;
}
.provider-logos .more-providers {
  font-size: 10px;
  font-weight: 400;
  letter-spacing: 0;
  gap: 5px;
}
.provider-logos .more-providers svg {
  width: 12px;
  height: 12px;
}
.section {
  padding-block: 78px;
}
.section-heading {
  text-align: center;
  margin-bottom: 35px;
}
.eyebrow {
  font-size: 10px;
  font-weight: 550;
  color: var(--blue-strong);
  letter-spacing: 1px;
  display: block;
  margin-bottom: 11px;
}
h2 {
  font-size: 31px;
  line-height: 1.5;
  letter-spacing: -1px;
  font-weight: 650;
}
.section-heading p {
  font-size: 12px;
  color: var(--muted-foreground);
  margin-top: 12px;
}
.features-section {
  border-block: 1px solid var(--border);
  background: var(--subtle);
}
.feature-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr;
  gap: 16px;
}
.feature-card {
  border: 1px solid var(--border);
  background: var(--card);
  border-radius: 12px;
  padding: 25px 24px 21px;
  min-width: 0;
  overflow: hidden;
  transition:
    box-shadow 0.2s,
    transform 0.2s;
}
.feature-card:hover {
  box-shadow: 0 8px 22px #293f6e09;
  transform: translateY(-2px);
}
.feature-icon {
  height: 34px;
  width: 34px;
  border: 1px solid color-mix(in srgb, var(--blue) 15%, transparent);
  border-radius: 9px;
  background: var(--accent);
  color: var(--blue);
  display: grid;
  place-items: center;
  margin-bottom: 20px;
}
.feature-icon.violet {
  color: #987bd0;
  background: #9678ce12;
  border-color: #9678ce20;
}
.feature-icon.green {
  color: #4aa88e;
  background: #4aa88e10;
  border-color: #4aa88e20;
}
.feature-card h3 {
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.3px;
  margin-bottom: 9px;
}
.feature-card > p {
  font-size: 11px;
  line-height: 1.9;
