}
.faq-list summary {
  list-style: none;
  padding: 19px 0;
  display: flex;
  justify-content: space-between;
  gap: 15px;
  font-size: 12px;
  cursor: pointer;
}
.faq-list summary::-webkit-details-marker {
  display: none;
}
.faq-list summary::after {
  content: '+';
