  width: max-content;
  margin: 15px auto 0;
  font-size: 9px;
  color: var(--muted-foreground);
}
.compare-link:hover {
  color: var(--blue);
}
.footer {
  border-top: 1px solid var(--border);
}
.footer-top {
  padding-block: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.footer .brand {
  font-size: 19px;
  gap: 8px;
}
.footer-top p {
  font-size: 10px;
  color: var(--muted-foreground);
  margin-top: 8px;
}
.footer-links {
  display: flex;
  gap: 28px;
  font-size: 11px;
  color: var(--muted-foreground);
}
.footer-links a:hover {
  color: var(--foreground);
}
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-block: 20px;
  display: flex;
  justify-content: space-between;
  gap: 15px;
  color: var(--muted-foreground);
  font-size: 9px;
}
.footer-bottom a:hover {
  text-decoration: underline;
}
.toast {
  position: fixed;
  left: 50%;
  bottom: 25px;
  z-index: 80;
  transform: translate(-50%, 15px);
  opacity: 0;
  pointer-events: none;
  padding: 11px 19px;
  background: var(--foreground);
  color: var(--background);
  border-radius: 8px;
  font-size: 12px;
  box-shadow: 0 6px 24px #0002;
  transition:
    opacity 0.2s,
    transform 0.2s;
  max-width: calc(100% - 30px);
  width: max-content;
}
.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}
[data-theme='dark'] .hero h1 > span {
  background-image: linear-gradient(110deg, #73b9ef 15%, #8aaef1 65%, #b0a2ed);
}
@keyframes blink {
  50% {
    opacity: 0;
  }
}
@keyframes travel {
  0% {
    left: 0;
    opacity: 0;
  }
  20% {
    opacity: 1;
  }
  80% {
    opacity: 1;
  }
  100% {
    left: 90%;
    opacity: 0;
  }
}
