/* Copied from New API web/src/styles/index.css. */
/* Micro-interactions — Vercel-style subtle hover/active feedback */
@media (prefers-reduced-motion: no-preference) {
  [data-slot='card']:not([data-card-hover='false']) {
    transition:
      transform 150ms ease,
      box-shadow 150ms ease;
  }

  @media (min-width: 641px) {
    [data-slot='card']:not([data-card-hover='false']):hover {
      transform: translateY(-1px);
      box-shadow: 0 4px 12px rgb(0 0 0 / 0.06);
    }

    .dark [data-slot='card']:not([data-card-hover='false']):hover {
      box-shadow: 0 4px 12px rgb(0 0 0 / 0.3);
    }
  }

  button:not(:disabled):active,
  [role='button']:not(:disabled):active {
    transform: scale(0.98);
  }

  [data-slot='table'] tr {
    transition: background-color 120ms ease;
  }

  /* Only fill the entrance delay; completed animations must release transform/opacity. */
  [data-slot='table'] tbody tr {
    animation: tableRowEnter 0.2s cubic-bezier(0.33, 1, 0.68, 1) backwards;
  }
  [data-slot='table'] tbody tr:nth-child(2) {
    animation-delay: 25ms;
  }
  [data-slot='table'] tbody tr:nth-child(3) {
    animation-delay: 50ms;
  }
  [data-slot='table'] tbody tr:nth-child(4) {
    animation-delay: 75ms;
  }
  [data-slot='table'] tbody tr:nth-child(5) {
    animation-delay: 100ms;
  }
  [data-slot='table'] tbody tr:nth-child(6) {
    animation-delay: 125ms;
  }
  [data-slot='table'] tbody tr:nth-child(7) {
    animation-delay: 150ms;
  }
  [data-slot='table'] tbody tr:nth-child(8) {
    animation-delay: 175ms;
  }
  [data-slot='table'] tbody tr:nth-child(9) {
    animation-delay: 200ms;
  }
  [data-slot='table'] tbody tr:nth-child(10) {
    animation-delay: 225ms;
  }
  [data-slot='table'] tbody tr:nth-child(n + 11) {
    animation-delay: 250ms;
  }
}

@keyframes tableRowEnter {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Standalone preview adapter. Layout lives in style.css; tokens and motion
   come directly from New API. References: Button, Card, Tabs, Badge,
   PublicHeader, Hero, ThemeSwitch and Sonner in the source project. */
:root {
  --sans: var(--font-body);
  --mono: var(--font-mono);
  --subtle: color-mix(in oklch, var(--muted) 40%, var(--background));
  --header: color-mix(in oklch, var(--background) 60%, transparent);
  --blue: var(--primary);
  --blue-strong: var(--secondary-foreground);
  --shadow: 0 8px 40px -12px rgb(0 0 0 / 8%);
}
.dark {
  --subtle: color-mix(in oklch, var(--muted) 40%, var(--background));
  --header: color-mix(in oklch, var(--background) 60%, transparent);
  --blue: var(--primary);
  --blue-strong: var(--secondary-foreground);
  --shadow: 0 8px 40px -12px rgb(0 0 0 / 30%);
}
html {
  font-family: var(--font-ui-sans);
}
body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.5;
}
button,
input,
select,
textarea {
  font-family: inherit;
}
pre,
code {
  font-family: var(--font-mono);
}
button,
a {
  -webkit-tap-highlight-color: transparent;
}
.icon {
  width: 16px;
  height: 16px;
}
.icon.small {
  width: 14px;
  height: 14px;
}
button:disabled {
  pointer-events: none;
  opacity: 0.5;
}

/* PublicHeader: 64px at top, compact 48px glass navigation after 20px scroll. */
.header {
  height: 64px;
  border: 0;
  background: transparent;
  backdrop-filter: none;
  transition: padding-top 700ms cubic-bezier(0.16, 1, 0.3, 1);
}
.header-inner {
  height: 64px;
  width: calc(100% - 48px);
  max-width: 1232px;
  padding-inline: 8px;
  gap: 8px;
  transition: all 700ms cubic-bezier(0.16, 1, 0.3, 1);
}
.header.scrolled {
  padding-top: 12px;
}
.header.scrolled .header-inner {
  height: 48px;
  max-width: 808px;
  width: calc(100% - 24px);
  padding-left: 16px;
  padding-right: 6px;
  border-radius: var(--radius-2xl);
  background: var(--header);
  backdrop-filter: blur(40px);
  box-shadow:
    0 0 0 0.5px color-mix(in oklch, var(--border) 50%, transparent),
    0 2px 16px -6px rgb(0 0 0 / 8%);
}
.dark .header.scrolled .header-inner {
  box-shadow:
    0 0 0 0.5px color-mix(in oklch, var(--border) 50%, transparent),
    0 2px 16px -6px rgb(0 0 0 / 40%);
}
.brand,
.footer .brand {
  font-family: inherit;
  font-size: var(--text-sm);
  font-weight: var(--font-weight-semibold);
  letter-spacing: var(--tracking-tight);
  gap: 10px;
  flex-shrink: 0;
}
.brand img,
.footer .brand img {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-lg);
  transition: transform 300ms var(--default-transition-timing-function);
}
.brand:hover img {
  transform: scale(1.05);
}
.navigation {
  margin-left: 0;
  gap: 2px;
}
.navigation a,
.login-link {
  font-size: var(--text-sm);
  font-weight: var(--font-weight-medium);
  line-height: 1.25rem;
  border-radius: var(--radius-lg);
  padding: 6px 12px;
  transition: color 200ms var(--default-transition-timing-function);
}
.navigation .nav-active,
.navigation a:hover {
  background: transparent;
  color: var(--foreground);
}
.header-actions {
  gap: 8px;
}
.header-divider {
  height: 16px;
  background: color-mix(in oklch, var(--border) 40%, transparent);
}

/* Button variants and sizes from components/ui/button.tsx. */
.button,
.hero-actions .button,
.final-cta .button {
  border-radius: var(--radius-lg);
  font-size: var(--text-sm);
  line-height: 1.25rem;
  font-weight: var(--font-weight-medium);
  min-height: 36px;
  gap: 6px;
  padding: 0 10px;
  background-clip: padding-box;
  user-select: none;
  box-shadow: none;
  transition: all var(--default-transition-duration)
    var(--default-transition-timing-function);
}
.hero-actions .button,
.final-cta .button {
  min-height: 44px;
  padding-inline: 20px;
}
.button:hover,
.button:active {
  transform: none;
  box-shadow: none;
}
.button:active:not([aria-haspopup]) {
  translate: 0 1px;
}
.button-primary {
  background: var(--primary);
  color: var(--primary-foreground);
}
a.button-primary:hover {
  background: color-mix(in oklch, var(--primary) 80%, transparent);
}
.button-outline {
  border-color: var(--border);
  background: var(--background);
  color: var(--foreground);
}
.button-outline:hover {
  background: var(--muted);
  color: var(--foreground);
}
.dark .button-outline {
  border-color: var(--input);
  background: color-mix(in oklch, var(--input) 30%, transparent);
}
.dark .button-outline:hover {
  background: color-mix(in oklch, var(--input) 50%, transparent);
}
.button-small,
.header-actions .button {
  min-height: 32px;
  padding-inline: 14px;
  font-size: var(--text-xs);
  font-weight: var(--font-weight-medium);
  gap: 6px;
}
.button .icon,
.hero-actions .icon,
.button-small .icon {
  width: 16px;
  height: 16px;
}
.icon-button {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-lg);
  color: var(--foreground);
}
.icon-button:hover {
  background: var(--muted);
}
.dark .icon-button:hover {
  background: color-mix(in oklch, var(--muted) 50%, transparent);
}
.theme-toggle {
  position: relative;
}
.theme-toggle .icon {
  width: 1.2rem;
  height: 1.2rem;
  transition: all 150ms var(--default-transition-timing-function);
}
.theme-toggle .moon-icon {
  position: absolute;
  transform: rotate(90deg) scale(0);
}
.dark .theme-toggle .sun-icon {
  transform: rotate(-90deg) scale(0);
}
.dark .theme-toggle .moon-icon {
  transform: rotate(0) scale(1);
}
button:focus-visible,
a:focus-visible,
summary:focus-visible,
[tabindex='0']:focus-visible {
  outline: 0;
  outline-offset: 0;
  border-color: var(--ring);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--ring) 50%, transparent);
}

/* Hero sizing and heading hierarchy from the existing landing components. */
.hero h1 {
  font-family: inherit;
  font-size: clamp(2.25rem, 4.5vw, 3.25rem);
  font-weight: var(--font-weight-bold);
  letter-spacing: var(--tracking-tight);
  line-height: 1.15;
}
.hero-description {
  font-size: 15px;
  line-height: 1.625;
}
.hero-description .copy-part {
  display: inline-block;
}
.hero-badge {
  padding: 6px 12px;
  font-size: 11px;
  font-weight: var(--font-weight-medium);
  border-radius: 9999px;
  box-shadow: 0 1px 2px rgb(0 0 0 / 5%);
}
.hero-badge > .icon:first-child,
.hero-badge .icon {
  width: 14px;
  height: 14px;
}
.hero-perks {
  font-size: var(--text-xs);
  gap: 24px;
}
.hero-perks .icon {
  width: 14px;
  height: 14px;
}
h2,
.final-cta h2,
.faq-heading h2 {
  font-size: var(--text-3xl);
  font-weight: var(--font-weight-bold);
  letter-spacing: var(--tracking-tight);
