  .navigation {
    display: none;
    position: absolute;
    top: 72px;
    left: 24px;
    right: 24px;
    padding: 12px;
    margin: 0;
    background: var(--popover);
    border: 1px solid var(--border);
    border-radius: var(--radius-xl);
    box-shadow: 0 4px 12px rgb(0 0 0 / 6%);
