  .response-content {
    min-height: 105px;
  }
  .request-footer .protocol-tag {
    display: block;
  }
  .feature-grid {
    gap: 16px;
  }
  .steps {
    gap: 24px;
  }
  .endpoint-copy {
    font-size: 11px;
    padding-inline: 6px;
    gap: 5px;
  }
