@media (max-width: 767px) {
  h2,
  .final-cta h2,
  .faq-heading h2 {
    font-size: var(--text-2xl);
  }
}
@media (max-width: 620px) {
  .header-inner {
    width: calc(100% - 24px);
    padding-inline: 4px;
  }
  .header.scrolled .header-inner {
    padding-left: 12px;
    padding-right: 6px;
  }
  .header-actions {
    gap: 4px;
  }
  .header-actions .button {
    font-size: var(--text-xs);
    padding-inline: 10px;
  }
  .header-actions .icon-button {
    width: 32px;
    height: 32px;
  }
  .navigation {
