/* CodeQ polish: neutral surfaces, CJK font metrics, two-column workbench. */
:root {
  --font-ui-sans:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Microsoft YaHei',
    'PingFang SC', 'Noto Sans CJK SC', sans-serif;
  --accent: color-mix(in srgb, var(--primary) 9%, var(--background));
}
.dark {
  --accent: color-mix(in srgb, var(--primary) 16%, var(--background));
}
.feature-icon,
.cta-icon,
.tool-icon,
.tool-icon.cherry,
.tool-icon.blue {
  background: var(--muted);
}
.model-option.selected {
  background: var(--accent);
}
.button,
.icon-button,
.code-tab,
.scenario-tabs button,
.catalog-footer button,
.endpoint-copy,
.catalog-type,
.feature-footnote,
.workspace-title,
.demo-tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1.25;
}
.icon,
.model-logo svg,
.catalog-logo svg,
.tool-icon svg {
  display: block;
  flex-shrink: 0;
}
.model-text {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
}
.model-text strong,
.model-text small {
  display: block;
  margin: 0;
  line-height: 1.4;
}
.workspace-body {
  grid-template-columns: 230px minmax(0, 1fr);
}
.request-panel {
  border-right: 0;
}
@media (max-width: 850px) {
  .workspace-body {
    grid-template-columns: 190px minmax(0, 1fr);
  }
}
@media (max-width: 620px) {
  .workspace-body {
    grid-template-columns: minmax(0, 1fr);
  }
}

html,
body {
  min-height: 0;
}
.hero {
  padding-top: 48px;
}
.compare-link {
  display: none;
}

